import unittest

class Test(unittest.TestCase):
    def test_finds_path(self):
        result = word_ladder_length('hit', 'cog', ['hot','dot','dog','lot','log','cog'])
        self.assertEqual(result, 5)
    def test_no_path_end_not_in_list(self):
        result = word_ladder_length('hit', 'cog', ['hot','dot','dog','lot','log'])
        self.assertEqual(result, 0)
    def test_direct_one_letter_change(self):
        result = word_ladder_length('hit', 'hot', ['hot'])
        self.assertEqual(result, 2)

if __name__ == '__main__':
    unittest.main()
